  void LayoutDeveloperBrowser(){if(developerBrowser==null)return;double width=developerBrowser.ActualWidth;bool wide=width>=1040,narrow=width<620;if(wide){compactRoots.Content=null;if(!developerBrowser.Children.Contains(developerRoots))developerBrowser.Children.Add(developerRoots);compactRoots.Visibility=Visibility.Collapsed;}else{developerBrowser.Children.Remove(developerRoots);compactRoots.Content=developerRoots;compactRoots.Visibility=Visibility.Visible;}developerBrowser.ColumnDefinitions[0].Width=wide?new GridLength(224):new GridLength(0);developerBrowser.ColumnDefinitions[1].Width=new GridLength(1,GridUnitType.Star);developerBrowser.ColumnDefinitions[2].Width=narrow?new GridLength(0):new GridLength(0.85,GridUnitType.Star);developerInspector.Visibility=Visibility.Visible;
