  ProjectEntry[] developerItems=new ProjectEntry[0];
  void SetDeveloperProjects(ProjectEntry[] projects){developerItems=projects;projectMetadataService=new DesktopService(root);var recent=vm.Service.State("project-recent");developerRows=projects.Select(p=>new ProjectRowState(p,DesktopService.S(recent,p.Id))).ToArray();FilterDeveloperProjects();}
  void FilterDeveloperProjects(){if(developerProjects==null)return;string query=developerSearch.Text;string active=SelectedDeveloperEntry()==null?developerSnapshot.SelectedProjectId:SelectedDeveloperEntry().Id;filteringProjects=true;try{developerProjects.ItemsSource=developerRows.Where(p=>(p.Name+" "+p.Directory).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToArray();developerProjects.SelectedItem=developerProjects.Items.Cast<ProjectRowState>().FirstOrDefault(p=>p.Entry.Id==active);}finally{filteringProjects=false;}if(developerProjects.SelectedItem!=null)DeveloperProjectChanged();else{projectGeneration++;lastDeveloperSelection=null;if(developerEnvironmentDetails!=null)developerEnvironmentDetails.Text="";if(developerQuickActions!=null)foreach(Button button in developerQuickActions.Children)button.IsEnabled=false;projectDetails.Text=developerProjects.Items.Count==0?"일치하는 프로젝트가 없습니다. 검색어를 지우거나 루트를 추가해 다시 탐색하세요.":"프로젝트를 선택하세요.";}}
  void DeveloperProjectChanged(){if(filteringProjects)return;var p=SelectedDeveloperEntry();if(p==null||p.Id==lastDeveloperSelection)return;lastDeveloperSelection=p.Id;int generation=++projectGeneration;int selectionGeneration=++developerSelectionGeneration;RefreshDeveloperDetails(p);var row=developerProjects.SelectedItem as ProjectRowState;projectSelectionRequest=Task.Factory.StartNew(()=>{lock(projectSelectionGate){if(selectionGeneration!=developerSelectionGeneration)return;var service=new DesktopService(root);service.RegisterDiscovered(p);service.SelectProject(p.Id);}});projectSelectionRequest.ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke((Action)delegate{if(task.IsFaulted){projectDetails.Text="프로젝트 확인 실패: "+task.Exception.GetBaseException().Message;return;}if(selectionGeneration==developerSelectionGeneration)developerSnapshot.SelectedProjectId=p.Id;if(generation!=projectGeneration||page!="developer-setup")return;LoadVisibleProjectRowSelection(row);});});}
  readonly object projectSelectionGate=new object();
  void RefreshDeveloperDetails(ProjectEntry p){
   var row=developerRows.FirstOrDefault(x=>x.Entry.Id==p.Id);if(row!=null)row.FavoriteChanged();
   projectDetails.Text=p.Name+"\n"+p.Directory+"\n"+(row==null?"유형 확인 중":row.Type+"\n"+row.Git);projectDetails.ToolTip=p.Directory;
   var defaults=developerSnapshot.Defaults;var prefs=p.Developer??defaults;
   if(developerEnvironmentDetails!=null)developerEnvironmentDetails.Text="WSL: "+(String.IsNullOrEmpty(prefs.WslDistribution)?defaults.WslDistribution??"미지정":prefs.WslDistribution)+"\n편집기: "+(String.IsNullOrEmpty(prefs.Editor)?defaults.Editor:prefs.Editor)+" · AI CLI: "+(String.IsNullOrEmpty(prefs.DefaultAiCli)?defaults.DefaultAiCli:prefs.DefaultAiCli);
   if(developerQuickActions!=null)foreach(Button button in developerQuickActions.Children){bool wsl=Convert.ToString(button.Content)=="Codex"||Convert.ToString(button.Content)=="OpenCode";button.IsEnabled=!busy&&(!wsl||!String.IsNullOrEmpty(String.IsNullOrEmpty(prefs.WslDistribution)?defaults.WslDistribution:prefs.WslDistribution));button.ToolTip=button.IsEnabled?null:"WSL 환경을 먼저 지정하세요.";ToolTipService.SetShowOnDisabled(button,true);}
  }
  void ShowProjectInfo(ProjectEntry p,ProjectInfo info){var row=developerRows.FirstOrDefault(x=>x.Entry.Id==p.Id);if(row!=null)row.SetInfo(info);RefreshDeveloperDetails(p);if(!String.IsNullOrEmpty(info.Error))projectDetails.Text+="\n"+info.Error;else if(!String.IsNullOrEmpty(info.Repository)&&!String.Equals(info.Repository.Replace('\\','/').TrimEnd('/'),p.Directory.Replace('\\','/').TrimEnd('/'),StringComparison.OrdinalIgnoreCase))projectDetails.Text+="\n저장소: "+info.Repository;}
  void EditDeveloperPreferences(ProjectEntry project){StackPanel panel;bool global=project==null;var w=EditorWindow(global?"전역 개발 기본값":"프로젝트 개발 설정",out panel);var data=global?vm.Service.Developer().Defaults:(project.Developer??new DeveloperPreferences());var inherited=vm.Service.Developer().Defaults;var fields=new Dictionary<string,ComboBox>();var dists=vm.Service.State("wsl-environments");var installed=dists.ContainsKey("Distributions")?((IEnumerable)dists["Distributions"]).Cast<object>().Select(Convert.ToString).ToArray():new string[0];foreach(string key in new[]{"TerminalHost","WslDistribution","DefaultAiCli","Editor","SessionPreset","WorkspaceProfile"}){var property=typeof(DeveloperPreferences).GetProperty(key);string value=property.GetValue(data,null) as string;string[] choices=key=="TerminalHost"?new[]{"windows-terminal","cmd"}:key=="DefaultAiCli"?new[]{"codex","opencode"}:key=="Editor"?new[]{"vscode"}:key=="WslDistribution"?installed:key=="WorkspaceProfile"?vm.Service.Profiles().Select(x=>x.Id).ToArray():vm.Service.Sessions().Presets.Select(x=>x.Id).ToArray();var options=new List<ChoiceOption>{new ChoiceOption("",global?"선택 안 함":"상속: "+Convert.ToString(property.GetValue(inherited,null)))};options.AddRange(choices.Concat(new[]{value}).Where(x=>!String.IsNullOrEmpty(x)).Distinct().Select(x=>new ChoiceOption(x,x)));fields[key]=Choice(panel,PreferenceLabel(key),options,value??"");}var user=EditBox(panel,"WSL 일반 계정 (빈 값: 등록 기본 계정 또는 유일한 일반 계정)",data.WslUser);var codex=EditBox(panel,"Codex 실행 이름 또는 Linux 경로",data.CodexExecutable);var opencode=EditBox(panel,"OpenCode 실행 이름 또는 Linux 경로",data.OpenCodeExecutable);panel.Children.Add(new TextBlock{Text="배포판 목록은 WSL 환경 페이지의 새로고침으로 갱신합니다. 빈 프로젝트 설정은 전역 값을 상속합니다.",Foreground=Muted,TextWrapping=TextWrapping.Wrap});SaveEditor(w,panel,()=>{var prefs=new DeveloperPreferences();foreach(var pair in fields)typeof(DeveloperPreferences).GetProperty(pair.Key).SetValue(prefs,Convert.ToString(pair.Value.SelectedValue),null);prefs.WslUser=user.Text.Trim();prefs.CodexExecutable=codex.Text.Trim();prefs.OpenCodeExecutable=opencode.Text.Trim();vm.Service.ValidatePreferences(prefs);if(global){var d=vm.Service.Developer();d.Defaults=prefs;vm.Service.SaveDeveloper(d);}else{project.Developer=prefs;vm.Service.SaveProject(project);}});if(!global){var reset=new Button{Content="프로젝트 지정값 모두 상속으로"};reset.Click+=delegate{foreach(var combo in fields.Values)combo.SelectedValue="";user.Text="";codex.Text="";opencode.Text="";};panel.Children.Add(reset);}w.ShowDialog();}
  static string PreferenceLabel(string key){return new Dictionary<string,string>{{"TerminalHost","터미널 호스트"},{"WslDistribution","WSL 배포판"},{"DefaultAiCli","기본 AI CLI"},{"Editor","편집기"},{"SessionPreset","기본 개발 세션"},{"WorkspaceProfile","작업공간 프로필"}}[key];}
  void EditDeveloperTool(){StackPanel panel;var w=EditorWindow("개발 도구 등록",out panel);var name=EditBox(panel,"도구 이름","");var path=EditBox(panel,"실행 파일 (.exe)","");var choose=new Button{Content="실행 파일 선택"};choose.Click+=delegate{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="실행 파일|*.exe"};if(dialog.ShowDialog(w)==true)path.Text=dialog.FileName;};panel.Children.Add(choose);SaveEditor(w,panel,()=>{var d=vm.Service.Developer();d.Tools.Add(new DeveloperTool{Id="tool-"+Guid.NewGuid().ToString("N"),Name=name.Text.Trim(),Executable=path.Text.Trim()});vm.Service.SaveDeveloper(d);});w.ShowDialog();}
  void BuildWslEnvironment(){Text("설치된 배포판을 선택해 개발 도구를 확인합니다.",true);environmentDetails=new TextBlock{Text="새로고침을 눌러 설치된 배포판을 읽으세요.",Foreground=Muted,TextWrapping=TextWrapping.Wrap};content.Children.Add(environmentDetails);var list=new ComboBox{Margin=new Thickness(0,10,0,10)};AutomationProperties.SetName(list,"WSL 배포판 선택");content.Children.Add(list);var a=Actions();Action(a,"배포판 새로고침",()=>{var names=vm.Service.Distributions();GuntConfiguration.Atomic(root,Path.Combine(root,"state","wsl-environments.json"),vm.Service.Json.Serialize(new {Distributions=names,Time=DateTimeOffset.Now.ToString("o")}),false);Dispatcher.Invoke((Action)(()=>{list.ItemsSource=names;if(names.Length>0)list.SelectedIndex=0;environmentDetails.Text=names.Length+"개 배포판을 찾았습니다.";}));return "배포판 목록을 갱신했습니다.";});Action(a,"선택 환경 도구 확인",()=>{string dist=Dispatcher.Invoke(new Func<string>(()=>list.SelectedItem as string));if(String.IsNullOrEmpty(dist))throw new ArgumentException("배포판을 선택하세요.");var tools=vm.Service.EnvironmentTools(dist);Dispatcher.Invoke((Action)(()=>environmentDetails.Text=dist+"\n"+String.Join("\n",tools.Select(x=>x.ToString()))));return "선택한 WSL의 Git·Node.js·Python·Codex·OpenCode를 확인했습니다.";});Action(a,"선택 배포판을 전역 기본값으로",()=>{string dist=Dispatcher.Invoke(new Func<string>(()=>list.SelectedItem as string));if(String.IsNullOrEmpty(dist))throw new ArgumentException("배포판을 선택하세요.");var d=vm.Service.Developer();d.Defaults.WslDistribution=dist;vm.Service.SaveDeveloper(d);return "전역 WSL 배포판을 저장했습니다. 프로젝트 지정값은 유지합니다.";});}
 }
